      "actionType": "",
      "webCategory": "Poste Windows",
      "script": "Show-SsitDiskAnalyzer }\n\n# ======================================================================================\n\n$script:SsitActivityDir=Join-Path $env:LOCALAPPDATA 'SuperSupportIT\\Activity'\n$script:SsitActivityFile=Join-Path $script:SsitActivityDir 'activity.csv'\ntry{New-Item -ItemType Directory -Path $script:SsitActivityDir -Force | Out-Null}catch{}\n\nfunction Write-SsitActivity {\n    param(\n        [string]$Action,\n        [string]$Module='Application',\n        [string]$Status='INFO',\n        [string]$Detail='',\n        [double]$DurationSeconds=0\n    )\n    try{\n        if([string]::IsNullOrWhiteSpace($Action)){$Action='Action non renseignee'}\n        if([string]::IsNullOrWhiteSpace($Module)){$Module='Application'}\n        if([string]::IsNullOrWhiteSpace($Status)){$Status='INFO'}\n        if(-not(Test-Path -LiteralPath $script:SsitActivityDir)){\n            New-Item -ItemType Directory -Path $script:SsitActivityDir -Force | Out-Null\n        }\n        $row=[pscustomobject][ordered]@{\n            Horodatage=(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')\n            Date=(Get-Date -Format 'yyyy-MM-dd')\n            Heure=(Get-Date -Format 'HH:mm:ss')\n            Action=$Action\n            Module=$Module\n            Statut=$Status\n            DureeSec=if($DurationSeconds -gt 0){[math]::Round($DurationSeconds,2)}else{''}\n            Utilisateur=$env:USERNAME\n            Poste=$env:COMPUTERNAME\n            Detail=([string]$Detail -replace '[\\r\\n]+',' ')\n        }\n        if(Test-Path -LiteralPath $script:SsitActivityFile){\n            $row | Export-Csv -LiteralPath $script:SsitActivityFile -Delimiter ';' -NoTypeInformation -Encoding UTF8 -Append\n        }else{\n            $row | Export-Csv -LiteralPath $script:SsitActivityFile -Delimiter ';' -NoTypeInformation -Encoding UTF8\n        }\n        return $true\n    }catch{\n        try{Write-Log (\"JOURNAL CSV ERREUR : \" + $_.Exception.Message)}catch{}\n        return $false\n    }\n}\n\nfunction Get-SsitActivityRows {\n    $rows=@()\n    try{\n        if(Test-Path -LiteralPath $script:SsitActivityFile){\n            $rows=@(Import-Csv -LiteralPath $script:SsitActivityFile -Delimiter ';' -ErrorAction Stop)\n            $rows=@($rows | Sort-Object @{Expression={\n                if($_.PSObject.Properties['Horodatage'] -and $_.Horodatage){[string]$_.Horodatage}\n                else{\"$($_.Date) $($_.Heure)\"}\n            }} -Descending)\n        }\n    }catch{\n        try{Write-Log (\"LECTURE JOURNAL CSV ERREUR : \" + $_.Exception.Message)}catch{}\n    }\n    return @($rows)\n}\n\nfunction Refresh-SsitActivityCenter {\n    param($Sender)\n    try{\n        $form=$null\n        if($Sender -is [Windows.Forms.Form]){$form=$Sender}else{$form=$Sender.FindForm()}\n        if($null -eq $form){return}\n        $grid=@($form.Controls.Find('SsitActivityGrid',$true)) | Select-Object -First 1\n        $status=@($form.Controls.Find('SsitActivityStatus',$true)) | Select-Object -First 1\n        if($null -eq $grid){return}\n        $rows=@(Get-SsitActivityRows)\n        $grid.DataSource=$null\n        $grid.DataSource=[Collections.ArrayList]@($rows)\n        if($status){\n            if($rows.Count -gt 0){$status.Text=\"$($rows.Count) entree(s) - $script:SsitActivityFile\"}\n            else{$status.Text=\"Aucune entree pour le moment - $script:SsitActivityFile\"}\n        }\n        $grid.Refresh()\n    }catch{\n        try{Write-Log (\"AFFICHAGE JOURNAL ERREUR : \" + $_.Exception.Message)}catch{}\n    }\n}\n\nfunction Show-SsitActivityCenter {\n    $f=New-Object Windows.Forms.Form\n    $f.Text='SUPER SUPPORT IT - Journal & Statistiques'\n    $f.Size=New-Object Drawing.Size(1280,760)\n    $f.StartPosition='CenterScreen'\n    $f.BackColor=[Drawing.Color]::White\n    Enable-Escape $f\n\n    $root=New-Object Windows.Forms.TableLayoutPanel\n    $root.Dock='Fill';$root.RowCount=3;$root.ColumnCount=1\n    [void]$root.RowStyles.Add((New-Object Windows.Forms.RowStyle([Windows.Forms.SizeType]::Absolute,42)))\n    [void]$root.RowStyles.Add((New-Object Windows.Forms.RowStyle([Windows.Forms.SizeType]::Percent,100)))\n    [void]$root.RowStyles.Add((New-Object Windows.Forms.RowStyle([Windows.Forms.SizeType]::Absolute,58)))\n    $f.Controls.Add($root)\n\n    $status=New-Object Windows.Forms.Label\n    $status.Name='SsitActivityStatus'\n    $status.Dock='Fill';$status.TextAlign='MiddleLeft';$status.Padding=New-Object Windows.Forms.Padding(12,0,0,0)\n    $status.Text='Chargement du journal...'\n    $root.Controls.Add($status,0,0)\n\n    $g=New-Object Windows.Forms.DataGridView\n    $g.Name='SsitActivityGrid'\n    Set-SsitReadableGrid $g\n    $g.Dock='Fill';$g.ReadOnly=$true;$g.AllowUserToAddRows=$false;$g.AllowUserToDeleteRows=$false\n    $g.RowHeadersVisible=$false;$g.SelectionMode='FullRowSelect';$g.MultiSelect=$true\n    $g.AutoSizeColumnsMode='Fill'\n    $root.Controls.Add($g,0,1)\n\n    $bar=New-Object Windows.Forms.FlowLayoutPanel\n    $bar.Dock='Fill';$bar.Padding=New-Object Windows.Forms.Padding(10,8,10,0)\n    $root.Controls.Add($bar,0,2)\n\n    $btnRefresh=New-Object Windows.Forms.Button\n    $btnRefresh.Text='Actualiser';$btnRefresh.Width=120;$btnRefresh.Height=34\n    $btnRefresh.Add_Click({param($sender,$e)Refresh-SsitActivityCenter $sender})\n    [void]$bar.Controls.Add($btnRefresh)\n\n    $btnFolder=New-Object Windows.Forms.Button\n    $btnFolder.Text='Ouvrir dossier';$btnFolder.Width=140;$btnFolder.Height=34\n    $btnFolder.Add_Click({try{Start-Process explorer.exe -ArgumentList \"`\"$script:SsitActivityDir`\"\"}catch{}})\n    [void]$bar.Controls.Add($btnFolder)\n\n    $btnTechnical=New-Object Windows.Forms.Button\n    $btnTechnical.Text='Journal technique';$btnTechnical.Width=150;$btnTechnical.Height=34\n    $btnTechnical.Add_Click({try{if(Test-Path -LiteralPath $script:LogFile){Start-Process notepad.exe -ArgumentList \"`\"$script:LogFile`\"\"}}catch{}})\n    [void]$bar.Controls.Add($btnTechnical)\n\n    $btnClose=New-Object Windows.Forms.Button\n    $btnClose.Text='Fermer';$btnClose.Width=110;$btnClose.Height=34\n    $btnClose.Add_Click({param($sender,$e)try{$sender.FindForm().Close()}catch{}})\n    [void]$bar.Controls.Add($btnClose)\n\n    Refresh-SsitActivityCenter $f\n    try{Apply-SsitLightThemeTree $f}catch{}\n    try{Register-SsitReliableCloseButtons $f}catch{}\n    $f.Show()\n    $f.Activate()",
